const input = $json || {};
const config = input.configSnapshot || input.config_snapshot || {};
const jira = config.jira || {};
const confluence = config.confluence || {};
const models = config.models || {};
const chroma = config.chroma || {};
const cleanBase = (value, fallback) => { const s = String(value || fallback); return s.endsWith('/') ? s.slice(0, -1) : s; };
const normalizeDocumentType = value => String(value || 'user_stories').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'user_stories';
const documentType = normalizeDocumentType(input.documentType || input.document_type || 'user_stories');
const rawChromaTopK = Number(chroma.topK || input.chromaTopK || 20);
const chromaTopK = Number.isFinite(rawChromaTopK) && rawChromaTopK > 0 ? rawChromaTopK : 20;
const retrievalSearchQueries = {
  user_stories: 'Project requirements for Agile epics user stories business rules functional requirements UI UX flows validation rules integrations acceptance criteria NFR risks constraints BRD FRD PRD SRS transcripts HLD LLD API data model',
  test_cases: 'Project test scenarios test cases acceptance criteria validation rules edge cases negative scenarios UI behavior API behavior business rules preconditions expected results',
  rtm: 'Project requirement traceability matrix BRD FRD requirement IDs acceptance criteria test coverage business rules source references',
  technical_design: 'Project architecture high level design low level design API database integration sequence flows components NFR performance security scalability',
  qa_document: 'Project QA strategy test plan test scenarios business rules acceptance criteria risks assumptions dependencies validation integration coverage'
};
return [{ json: {
  jobId: input.jobId || input.job_id || 'JOB-' + Date.now(),
  projectName: input.projectName || input.project_name || 'Unknown Project',
  documentType,
  productOwner: input.productOwner || input.product_owner || 'Product Owner',
  projectId: input.projectId || input.project_id || null,
  requestedBy: input.requestedBy || input.requested_by || null,
  settingsVersion: input.settingsVersion || input.settings_version || null,
  environmentKey: config.environment?.key || input.environment || 'local',
  startedAt: input.startedAt || input.createdAt || new Date().toISOString(),
  jiraProjectType: 'team-managed',
  jiraProjectKey: input.jiraProjectKey || jira.projectKey || 'KAN',
  jiraProjectId: input.jiraProjectId || jira.projectId || null,
  jiraBaseUrl: cleanBase(input.jiraBaseUrl || jira.baseUrl, 'https://anujalhans1.atlassian.net'),
  epicIssueTypeId: input.epicIssueTypeId || jira.epicIssueTypeId || null,
  storyIssueTypeId: input.storyIssueTypeId || jira.storyIssueTypeId || null,
  epicIssueTypeName: input.epicIssueTypeName || jira.epicIssueType || jira.epicIssueTypeName || 'Epic',
  storyIssueTypeName: input.storyIssueTypeName || jira.storyIssueType || jira.storyIssueTypeName || 'Story',
  idempotencyLabelPrefix: input.idempotencyLabelPrefix || jira.idempotencyLabelPrefix || 'qops',
  confluenceBaseUrl: cleanBase(input.confluenceBaseUrl || confluence.baseUrl, 'https://anujalhans1.atlassian.net/wiki'),
  confluenceSpaceKey: input.confluenceSpaceKey || confluence.spaceKey || 'TD',
  confluenceParentPageId: input.confluenceParentPageId || confluence.parentPageId || null,
  generationModel: models.generationModel || input.generationModel || 'gpt-4.1-mini',
  maxTokens: Math.max(16000, Number(models.maxTokens || input.maxTokens || 16000) || 16000),
  chromaCollection: chroma.collection || input.chromaCollection || 'qa-chunks-batches',
  chromaTopK,
  retrievalProfileKey: documentType,
  retrievalSearchQuery: 'Project ' + (input.projectName || input.project_name || 'Unknown Project') + ' ' + (retrievalSearchQueries[documentType] || retrievalSearchQueries.qa_document)
}}];

