const generated = $json.output || $json;
let context;
try { context = $('Check Chroma Retrieval Quality').first().json; } catch (error) { context = $('Normalize Team Managed Request').first().json; }
const toObjectArray = value => {
  if (Array.isArray(value)) return value.filter(item => item && typeof item === 'object');
  if (value && typeof value === 'object') return Object.values(value).filter(item => item && typeof item === 'object');
  return [];
};

const firstText = (...values) => {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
};

const normalizeKey = value => firstText(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
const generatedBacklog = generated.backlog && typeof generated.backlog === 'object' ? generated.backlog : {};

const normalizeEpic = (epic, index) => {
  const copy = { ...epic };
  const epicId = firstText(copy.epicCorrelationId, copy.epicId, copy.id, copy.key, copy.referenceId, 'EPIC-' + String(index + 1).padStart(3, '0'));
  copy.epicCorrelationId = firstText(copy.epicCorrelationId, copy.epicId, copy.id, copy.key, epicId);
  copy.epicId = firstText(copy.epicId, copy.epicCorrelationId, epicId);
  copy.epicName = firstText(copy.epicName, copy.name, copy.title, copy.feature, copy.summary, 'Generated Epic ' + String(index + 1));
  copy.epicSummary = firstText(copy.epicSummary, copy.epicDescription, copy.description, copy.businessOutcome, copy.summary);
  copy.businessOutcome = firstText(copy.businessOutcome, copy.businessObjective, copy.outcome, copy.epicSummary);
  return copy;
};

const normalizeStory = (story, epic, index) => {
  const copy = { ...story };
  const epicId = firstText(epic?.epicCorrelationId, epic?.epicId, copy.epicCorrelationId, copy.epicId, copy.parentEpicId, 'EPIC-001');
  const storyId = firstText(copy.storyCorrelationId, copy.userStoryId, copy.storyId, copy.id, copy.key, epicId + '-US-' + String(index + 1).padStart(3, '0'));
  copy.storyCorrelationId = firstText(copy.storyCorrelationId, copy.userStoryId, copy.storyId, storyId);
  copy.userStoryId = firstText(copy.userStoryId, copy.storyCorrelationId, storyId);
  copy.epicCorrelationId = firstText(copy.epicCorrelationId, copy.epicId, copy.parentEpicId, epicId);
  copy.epicId = firstText(copy.epicId, copy.epicCorrelationId, epicId);
  copy.summary = firstText(copy.summary, copy.title, copy.name, copy.feature, String(copy.userStory || '').slice(0, 120));
  copy.feature = firstText(copy.feature, copy.summary, epic?.epicName);
  copy.userStory = firstText(copy.userStory, copy.story, copy.description, copy.userStoryDescription, copy.summary);
  copy.userStoryDescription = firstText(copy.userStoryDescription, copy.description, copy.userStory);
  copy.acceptanceCriteria = copy.acceptanceCriteria ?? copy.acceptance_criteria ?? copy.ac ?? copy.criteria ?? [];
  copy.sourceReferences = copy.sourceReferences ?? copy.sourceTraceability ?? copy.traceability ?? [];
  return copy;
};

let epics = [
  ...toObjectArray(generated.epics),
  ...toObjectArray(generatedBacklog.epics),
  ...toObjectArray(generated.features),
  ...toObjectArray(generatedBacklog.features)
].map(normalizeEpic);

const seenEpicIds = new Set();
epics = epics.filter(epic => {
  const key = normalizeKey(firstText(epic.epicCorrelationId, epic.epicId, epic.epicName));
  if (!key || seenEpicIds.has(key)) return false;
  seenEpicIds.add(key);
  return true;
});

for (const [epicIndex, epic] of epics.entries()) {
  const nestedStories = [
    ...toObjectArray(epic.stories),
    ...toObjectArray(epic.userStories),
    ...toObjectArray(epic.children),
    ...toObjectArray(epic.items)
  ];
  epic.stories = nestedStories.map((story, storyIndex) => normalizeStory(story, epic, storyIndex));
}

const topLevelStories = [
  ...toObjectArray(generated.stories),
  ...toObjectArray(generated.userStories),
  ...toObjectArray(generatedBacklog.stories),
  ...toObjectArray(generatedBacklog.userStories)
];

const epicKeys = epic => new Set([
  epic.epicCorrelationId,
  epic.epicId,
  epic.id,
  epic.key,
  epic.epicName,
  epic.name,
  epic.title,
  epic.feature,
  epic.summary
].map(normalizeKey).filter(Boolean));

const storyEpicKeys = story => [
  story.epicCorrelationId,
  story.epicId,
  story.parentEpicId,
  story.parentEpicCorrelationId,
  story.epicName,
  story.epic,
  story.feature,
  story.module,
  story.domain
].map(normalizeKey).filter(Boolean);

const groupUnmatchedStories = new Map();
for (const rawStory of topLevelStories) {
  const keys = storyEpicKeys(rawStory);
  let targetEpic = epics.find(epic => {
    const keysForEpic = epicKeys(epic);
    return keys.some(key => keysForEpic.has(key));
  });

  if (!targetEpic && epics.length === 1) targetEpic = epics[0];

  if (targetEpic) {
    targetEpic.stories.push(normalizeStory(rawStory, targetEpic, targetEpic.stories.length));
  } else {
    const groupName = firstText(rawStory.epicName, rawStory.epic, rawStory.feature, rawStory.module, rawStory.domain, 'Generated Backlog');
    const key = normalizeKey(groupName) || 'generatedbacklog';
    if (!groupUnmatchedStories.has(key)) groupUnmatchedStories.set(key, { name: groupName, stories: [] });
    groupUnmatchedStories.get(key).stories.push(rawStory);
  }
}

for (const group of groupUnmatchedStories.values()) {
  const epic = normalizeEpic({
    epicName: group.name,
    epicSummary: 'Generated from top-level user stories returned by the backlog model.',
    businessOutcome: 'Create a Jira-ready backlog from retrieved project evidence.'
  }, epics.length);
  epic.stories = group.stories.map((story, storyIndex) => normalizeStory(story, epic, storyIndex));
  epics.push(epic);
}

generated.epics = epics;
const fatalErrors = [];

const normalizeArray = value => {
  if (Array.isArray(value)) return value.map(v => typeof v === 'string' ? v.trim() : JSON.stringify(v)).filter(Boolean);
  if (typeof value === 'string' && value.trim()) return [value.trim()];
  return [];
};

let sourceCoverage = normalizeArray(generated.document?.sourceCoverage);
let retrievalEvidence = Array.isArray(generated.document?.retrievalEvidence) ? generated.document.retrievalEvidence : [];

const preflightRetrievalContext = Array.isArray(context.retrievalContext) ? context.retrievalContext : [];
const preflightCoverage = [...new Set(preflightRetrievalContext.map(chunk => {
  const docType = String(chunk.docType || chunk.metadata?.docType || 'Source').trim();
  const source = String(chunk.source || chunk.fileName || chunk.metadata?.fileName || chunk.metadata?.filename || '').trim();
  const section = String(chunk.section || chunk.sectionTitle || chunk.metadata?.sectionTitle || '').trim();
  return [docType, source, section].filter(Boolean).join(' - ');
}).filter(Boolean))];

if (!sourceCoverage.length && preflightCoverage.length) {
  sourceCoverage = preflightCoverage;
}

if (!retrievalEvidence.length && preflightRetrievalContext.length) {
  retrievalEvidence = preflightRetrievalContext.slice(0, 20).map(chunk => ({
    source: chunk.source || chunk.fileName || 'Chroma chunk',
    docType: chunk.docType || 'UNKNOWN',
    section: chunk.section || chunk.sectionTitle || '',
    chunkId: chunk.chunkId || '',
    contentSource: chunk.contentSource || '',
    profileScore: chunk.profileScore || null
  }));
}

if (!generated.document || typeof generated.document !== 'object') {
  generated.document = {};
}
generated.document.sourceCoverage = sourceCoverage;
generated.document.retrievalEvidence = retrievalEvidence;

if (!context.retrievalQuality || Number(context.retrievalQuality.chunkCount || 0) < 1) {
  fatalErrors.push('Preflight Chroma retrieval returned 0 chunks for project=' + (context.projectName || 'Unknown Project') + '.');
}
if (!sourceCoverage.length && !retrievalEvidence.length) {
  fatalErrors.push('No Chroma retrieval evidence is available from either the model response or preflight retrieval. Refusing to create Jira issues from fallback-only content. Check Chroma metadata filter, project ingestion, and whether chunks exist for project=' + (context.projectName || 'Unknown Project') + '.');
}
if (!epics.length) fatalErrors.push('No epics were generated.');

const epicNames = new Set();
const storySummaries = new Set();
let totalStories = 0;

for (const [epicIndex, epic] of epics.entries()) {
  const epicId = epic.epicCorrelationId || epic.epicId || `EPIC-${String(epicIndex + 1).padStart(3, '0')}`;
  epic.epicCorrelationId = epic.epicCorrelationId || epic.epicId || epicId;
  epic.epicName = epic.epicName || epic.feature || '';
  epic.epicSummary = epic.epicSummary || epic.epicDescription || epic.businessOutcome || '';
  epic.businessOutcome = epic.businessOutcome || epic.businessObjective || '';
  epic.sourceReferences = normalizeArray(epic.sourceReferences).concat(normalizeArray(epic.sourceTraceability));
  epic.sourceReferences = [...new Set(epic.sourceReferences)];
  epic.successMetrics = normalizeArray(epic.successMetrics);
  epic.priority = epic.priority || 'Medium';
  epic.storyCountRationale = epic.storyCountRationale || epic.decompositionRationale || epic.scopeRationale || '';

  if (!epic.epicCorrelationId) fatalErrors.push('Epic at index ' + epicIndex + ' is missing epicCorrelationId.');
  if (!epic.epicName || String(epic.epicName).trim().length < 8) fatalErrors.push('Epic ' + epicId + ' has a missing or weak epicName.');
  const epicName = String(epic.epicName || '').trim().toLowerCase();
  if (epicName && epicNames.has(epicName)) fatalErrors.push('Duplicate epic name: ' + epic.epicName);
  if (epicName) epicNames.add(epicName);
  if (!epic.sourceReferences.length) fatalErrors.push('Epic ' + epicId + ' has no source references.');

  epic.stories = Array.isArray(epic.stories) ? epic.stories : [];
  if (!epic.stories.length) {
    fatalErrors.push('Epic ' + epicId + ' has zero stories. Adaptive story count is allowed, but every epic must have at least one valid child story or it cannot be linked cleanly in Jira.');
    continue;
  }

  totalStories += epic.stories.length;

  for (const [storyIndex, story] of epic.stories.entries()) {
    const storyId = story.storyCorrelationId || story.userStoryId || `${epicId}-US-${String(storyIndex + 1).padStart(3, '0')}`;
    story.storyCorrelationId = story.storyCorrelationId || story.userStoryId || storyId;
    story.summary = story.summary || story.feature || String(story.userStory || '').slice(0, 120) || '';
    story.feature = story.feature || story.summary;
    story.userStoryDescription = story.userStoryDescription || story.description || '';
    story.businessContext = story.businessContext || epic.businessOutcome || epic.businessObjective || '';
    story.acceptanceCriteria = normalizeArray(story.acceptanceCriteria);
    story.alternateFlows = normalizeArray(story.alternateFlows);
    story.exceptionHandling = normalizeArray(story.exceptionHandling);
    story.uiUxRequirements = normalizeArray(story.uiUxRequirements);
    story.fieldValidationRules = normalizeArray(story.fieldValidationRules);
    story.dataIntegrationRequirements = normalizeArray(story.dataIntegrationRequirements);
    story.performanceNFRs = normalizeArray(story.performanceNFRs);
    story.testScenarios = normalizeArray(story.testScenarios);
    story.dependencies = normalizeArray(story.dependencies);
    story.assumptions = normalizeArray(story.assumptions);
    story.nonFunctionalConsiderations = normalizeArray(story.nonFunctionalConsiderations);
    story.testNotes = normalizeArray(story.testNotes);
    story.sourceReferences = normalizeArray(story.sourceReferences).concat(normalizeArray(story.sourceTraceability));
    if (!story.sourceReferences.length && epic.sourceReferences.length) story.sourceReferences = epic.sourceReferences;
    story.sourceReferences = [...new Set(story.sourceReferences)];

    if (!story.storyCorrelationId) fatalErrors.push('Story under ' + epicId + ' missing storyCorrelationId.');
    if (!story.summary || String(story.summary).trim().length < 8) fatalErrors.push('Story ' + storyId + ' has a missing or weak summary.');
    const storySummary = String(story.summary || '').trim().toLowerCase();
    if (storySummary && storySummaries.has(storySummary)) fatalErrors.push('Duplicate story summary: ' + story.summary);
    if (storySummary) storySummaries.add(storySummary);
    const userStoryText = String(story.userStory || '').trim();
    story.userStoryFormat = /^As a\b/i.test(userStoryText) ? 'canonical' : (userStoryText ? 'narrative_statement' : 'missing');
    if (!userStoryText && story.summary) {
      story.userStory = story.summary;
      story.userStoryFormat = 'derived_from_summary';
    }
    if (story.acceptanceCriteria.length < 1) fatalErrors.push('Story ' + storyId + ' has no acceptance criteria.');
    const hasGivenWhenThenCriteria = story.acceptanceCriteria.some(a => /given.+when.+then/i.test(String(a)));
    story.acceptanceCriteriaFormat = hasGivenWhenThenCriteria ? 'given_when_then' : 'testable_statement';
    if (!story.sourceReferences.length) fatalErrors.push('Story ' + storyId + ' has no source references.');
  }
}

if (!totalStories) fatalErrors.push('No user stories were generated across the backlog.');
if (fatalErrors.length) throw new Error('Backlog quality gate failed: ' + [...new Set(fatalErrors)].join(' | '));

const textForTokens = JSON.stringify(generated);
const tokensOutput = Math.max(1, Math.ceil(textForTokens.length / 4));
const prompt = $('Professional Prompt Library').first().json;
const tokensInput = Math.max(1, Math.ceil(((prompt.system || '') + (prompt.user || '')).length / 4));
const estimatedCostUsd = Number(((tokensInput * 0.40 / 1000000) + (tokensOutput * 1.60 / 1000000)).toFixed(6));

return [{
  json: {
    ...context,
    generated,
    epics,
    wordCount: textForTokens.split(/\s+/).length,
    tokensInput,
    tokensOutput,
    tokensTotal: tokensInput + tokensOutput,
    estimatedCostUsd,
    qualityGate: {
      passed: true,
      status: 'passed',
      jiraProjectType: 'team-managed',
      adaptiveStoryCount: true,
      epicCount: epics.length,
      storyCount: totalStories,
      sourceCoverage,
      retrievalEvidenceCount: retrievalEvidence.length
    }
  }
}];

const root = $json;

const cleanText = value => {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map(cleanText).filter(Boolean).join('\n');
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value).replace(/\r/g, '').trim();
};

const traceLine = value => {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map(traceLine).filter(Boolean).join('\n');
  if (typeof value === 'string') {
    const text = value.trim();
    if (!text || text === '[object Object]') return '';
    if (text.startsWith('{') || text.startsWith('[')) {
      try { return traceLine(JSON.parse(text)); } catch (error) {}
    }
    return text;
  }
  if (typeof value === 'object') {
    const parts = [];
    const source = value.source || value.fileName || value.file_name || value.document || value.documentType || value.document_type || value.title;
    const section = value.section || value.heading || value.page || value.chunkId || value.chunk_id;
    const excerpt = value.excerpt || value.text || value.content || value.evidence || value.summary;
    const score = value.score ?? value.similarity ?? value.distance;
    if (source) parts.push('Source: ' + cleanText(source));
    if (section) parts.push('Section: ' + cleanText(section));
    if (excerpt) parts.push('Evidence: ' + cleanText(excerpt).slice(0, 500));
    if (score !== undefined && score !== null) parts.push('Score: ' + String(score));
    if (parts.length) return parts.join(' | ');
    return Object.entries(value)
      .filter(([_, v]) => v !== null && v !== undefined && typeof v !== 'object')
      .map(([k, v]) => k + ': ' + cleanText(v))
      .join(' | ');
  }
  return cleanText(value);
};

const traceList = (...values) => values
  .flatMap(value => Array.isArray(value) ? value : [value])
  .map(traceLine)
  .flatMap(line => cleanText(line).split(/\n+/))
  .map(line => line.trim())
  .filter(Boolean);

const normalizeArray = value => {
  if (Array.isArray(value)) return value.map(cleanText).filter(Boolean);
  const text = cleanText(value);
  if (!text) return [];
  return text.split(/\n+/).map(line => line.replace(/^[-*]\s*/, '').trim()).filter(Boolean);
};

const labelSafe = value => String(value || '').toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const mark = type => ({ type });
const textNode = (value, marks = []) => {
  const text = cleanText(value).slice(0, 12000);
  if (!text) return null;
  return marks.length ? { type: 'text', text, marks } : { type: 'text', text };
};
const paragraph = (...parts) => ({ type: 'paragraph', content: parts.flat().filter(Boolean) });
const heading = (value, level = 3) => ({ type: 'heading', attrs: { level }, content: [textNode(value)] });
const rule = () => ({ type: 'rule' });
const labeledParagraph = (label, value) => {
  const text = cleanText(value);
  if (!text) return null;
  return paragraph(textNode(label + ': ', [mark('strong')]), textNode(text));
};
const bulletList = values => {
  const items = normalizeArray(values);
  if (!items.length) return null;
  return {
    type: 'bulletList',
    content: items.slice(0, 40).map(item => ({ type: 'listItem', content: [paragraph(textNode(item))] }))
  };
};
const orderedList = values => {
  const items = normalizeArray(values);
  if (!items.length) return null;
  return {
    type: 'orderedList',
    attrs: { order: 1 },
    content: items.slice(0, 40).map(item => ({ type: 'listItem', content: [paragraph(textNode(item))] }))
  };
};

const sourceLabelMap = {
  BRD: 'Business requirements document',
  FRD: 'Functional requirements document',
  PRD: 'Product requirements document',
  SRS: 'Software requirements specification',
  HLD: 'High-level design',
  LLD: 'Low-level design',
  UI_UX: 'UI/UX artifact',
  API_SPEC: 'API specification',
  DATA_MODEL: 'Data model',
  TRANSCRIPT: 'Stakeholder transcript',
  TEST_CASES: 'Test cases',
  TEST_PLAN: 'Test plan',
  UNKNOWN: 'Source document'
};

const normalizeSourceType = value => {
  const text = cleanText(value).toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (!text) return 'UNKNOWN';
  if (text === 'UI' || text === 'UX' || text === 'UIUX' || text === 'UI_UX') return 'UI_UX';
  if (text === 'API' || text === 'API_SPECIFICATION') return 'API_SPEC';
  if (text === 'DATA' || text === 'DATA_MODEL_DOCUMENT') return 'DATA_MODEL';
  if (text === 'TEST_CASE' || text === 'TEST_CASES_DOCUMENT') return 'TEST_CASES';
  if (text === 'TEST_PLAN_DOCUMENT') return 'TEST_PLAN';
  return text;
};

const sourceLabel = value => {
  const type = normalizeSourceType(value);
  if (sourceLabelMap[type]) return sourceLabelMap[type];
  return type.toLowerCase().replace(/_/g, ' ').replace(/\b\w/g, char => char.toUpperCase()) || 'Source document';
};

const chunkPrefix = value => {
  const text = cleanText(value);
  if (!text) return '';
  return (text.split('|')[0] || text).replace(/\.+$/g, '').slice(0, 12);
};

const shortChunkId = value => {
  const prefix = chunkPrefix(value);
  if (!prefix) return '';
  return cleanText(value).length > prefix.length ? prefix + '...' : prefix;
};

const parseTraceText = textValue => {
  const text = cleanText(textValue);
  if (!text) return [];
  if (text.includes(';')) return text.split(';').flatMap(part => parseTraceText(part));
  const typeMatch = text.match(/\b(BRD|FRD|PRD|SRS|HLD|LLD|UI[\s_/-]*UX|API[\s_/-]*SPEC|DATA[\s_/-]*MODEL|TRANSCRIPT|TEST[\s_/-]*(?:CASES?|PLAN)|UNKNOWN)\b/i);
  const sourceType = normalizeSourceType(typeMatch ? typeMatch[1] : '');
  const chunkMatch = text.match(/(?:chunk\s+|\/)([A-Za-z0-9-]+(?:\.\.\.)?(?:\|[^\s;,)]*)?)/i);
  const chunkId = chunkMatch ? chunkMatch[1] : '';
  const pipeParts = chunkId ? chunkId.split('|') : [];
  const section = pipeParts.length > 1 ? pipeParts[1] : '';
  const contentSource = pipeParts.length > 3 ? pipeParts[3] : '';
  if (typeMatch || chunkId) {
    return [{ sourceType, chunkId, section, contentSource, raw: text }];
  }
  return [{ sourceType: 'UNKNOWN', evidence: text, raw: text }];
};

const parseTraceEntry = value => {
  if (value === null || value === undefined) return [];
  if (Array.isArray(value)) return value.flatMap(parseTraceEntry);
  if (typeof value === 'object') {
    const sourceType = normalizeSourceType(value.docType || value.documentType || value.sourceType || value.artifactType || value.source || value.documentCategory);
    const chunkId = cleanText(value.chunkId || value.chunk_id || value.id || '');
    const section = cleanText(value.sectionTitle || value.section || value.heading || value.page || value.pageNumber || value.chunkIndex || '');
    const contentSource = cleanText(value.contentSource || value.sourceFormat || value.mode || '');
