const traceLine = value => {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map(traceLine).filter(Boolean).join('\n');
  if (typeof value === 'string') {
    const text = value.trim();
    if (!text || text === '[object Object]') return '';
    if (text.startsWith('{') || text.startsWith('[')) {
      try { return traceLine(JSON.parse(text)); } catch (error) {}
    }
    return text;
  }
  if (typeof value === 'object') {
    const parts = [];
    const source = value.source || value.fileName || value.file_name || value.document || value.documentType || value.document_type || value.title;
    const section = value.section || value.heading || value.page || value.chunkId || value.chunk_id;
    const excerpt = value.excerpt || value.text || value.content || value.evidence || value.summary;
    const score = value.score ?? value.similarity ?? value.distance;
    if (source) parts.push('Source: ' + cleanText(source));
    if (section) parts.push('Section: ' + cleanText(section));
    if (excerpt) parts.push('Evidence: ' + cleanText(excerpt).slice(0, 500));
    if (score !== undefined && score !== null) parts.push('Score: ' + String(score));
    if (parts.length) return parts.join(' | ');
    return Object.entries(value)
      .filter(([_, v]) => v !== null && v !== undefined && typeof v !== 'object')
      .map(([k, v]) => k + ': ' + cleanText(v))
      .join(' | ');
  }
  return cleanText(value);
};

