  if (profile.primaryDocTypes.includes(docType)) {
    profileScore += 40;
    reasons.push('primary docType ' + docType);
  } else if (profile.secondaryDocTypes.includes(docType)) {
    profileScore += 22;
    reasons.push('secondary docType ' + docType);
  } else if (!docType || docType === 'UNKNOWN') {
    profileScore += 2;
    reasons.push('unclassified docType fallback');
  }

  if (profile.preferredCategories.includes(documentCategory)) {
    profileScore += 18;
    reasons.push('category ' + documentCategory);
  }

  if (profile.preferredArtifacts.includes(artifactType)) {
    profileScore += 18;
    reasons.push('artifact ' + artifactType);
