  let context = {};
  try {
    const request = $('Normalize Team Managed Request').first().json || {};
    const prompt = $('Professional Prompt Library').first().json || {};
    const quality = $('Check Chroma Retrieval Quality').first().json?.retrievalQuality || {};
    context = {
      jobId: request.jobId,
      projectName: request.projectName,
      documentType: request.documentType,
      generationModel: request.generationModel,
      maxTokens: request.maxTokens,
      chromaTopK: request.chromaTopK,
      selectedChunkCount: quality.selectedChunkCount,
      promptChars: String((prompt.system || '') + (prompt.user || '')).length,
      outputChars: text.length
    };
  } catch (error) {}

  return [
    'Backlog parser detected incomplete or truncated model JSON. Jira and Confluence creation stopped before any issues/pages were created.',
    extra,
    'Action: rerun with maxTokens >= 16000, reduce retrieval context/topK, or split backlog generation into skeleton + enrichment steps.',
    'Context: ' + JSON.stringify(context)
  ].filter(Boolean).join(' ');
};

const extractBalancedJsonObject = text => {
  const firstBrace = text.indexOf('{');
  if (firstBrace < 0) {
    throw new Error('Backlog parser received a response without a JSON object. Raw preview: ' + text.slice(0, 500));
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = firstBrace; i < text.length; i++) {
    const char = text[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
    } else if (char === '{') {
      depth += 1;
    } else if (char === '}') {
      depth -= 1;
      if (depth === 0) {
        return {
          candidate: text.slice(firstBrace, i + 1),
          trailing: text.slice(i + 1).trim()
        };
      }
      if (depth < 0) break;
    }
  }

  const partial = text.slice(firstBrace);
  throw new Error(truncationMessage(
    text,
    'No complete balanced JSON object was found. JSON balance: {' + count(partial, /{/g) + '/' + count(partial, /}/g) + '} [' + count(partial, /\[/g) + '/' + count(partial, /\]/g) + '].'
  ));
};

const parseCandidate = (value) => {
  if (value && typeof value === 'object' && value.document && Array.isArray(value.epics)) return value;
  if (value && typeof value === 'object' && value.output?.document && Array.isArray(value.output.epics)) return value.output;

  let text = stringifyRaw(value);
  if (!text) throw new Error('Backlog parser received an empty model response.');

  const fenced = text.match(new RegExp('\\x60{3}(?:json)?\\s*([\\s\\S]*?)\\s*\\x60{3}', 'i'));
  if (fenced) text = fenced[1].trim();

  for (let i = 0; i < 2; i++) {
    const trimmed = text.trim();
    if (!(trimmed.startsWith('"') && trimmed.endsWith('"'))) break;
    try {
      const unwrapped = JSON.parse(trimmed);
      if (unwrapped && typeof unwrapped === 'object') return unwrapped;
      if (typeof unwrapped === 'string') text = unwrapped.trim();
    } catch (error) {
      break;
    }
  }

  const { candidate, trailing } = extractBalancedJsonObject(text);
  try {
    return JSON.parse(candidate);
  } catch (error) {
    const position = String(error.message || '').match(/position\s+(\d+)/i)?.[1];
    const pos = position ? Number(position) : -1;
    const near = pos >= 0 ? candidate.slice(Math.max(0, pos - 300), Math.min(candidate.length, pos + 300)) : candidate.slice(0, 500);
    const openBraces = count(candidate, /{/g);
    const closeBraces = count(candidate, /}/g);
    const openBrackets = count(candidate, /\[/g);
    const closeBrackets = count(candidate, /\]/g);
    const completionLike = openBraces !== closeBraces || openBrackets !== closeBrackets || /("[^"]*|[,:\[{]\s*)$/.test(candidate.trim());
    if (completionLike) {
      throw new Error(truncationMessage(text, error.message + '. JSON balance: {' + openBraces + '/' + closeBraces + '} [' + openBrackets + '/' + closeBrackets + ']. Near parse error: ' + near));
    }
    throw new Error('Backlog parser failed to parse model JSON: ' + error.message + '. Near parse error: ' + near);
  }
};

let parsed;
try {
  parsed = parseCandidate(raw);
} catch (error) {
  throw new Error(error.message);
}

const generated = parsed.output && typeof parsed.output === 'object' ? parsed.output : parsed;
if (!generated.document || typeof generated.document !== 'object') generated.document = {};

const hasItems = value => Array.isArray(value) && value.length > 0;
const hasBacklogShape =
  hasItems(generated.epics) ||
  hasItems(generated.stories) ||
  hasItems(generated.userStories) ||
  hasItems(generated.features) ||
  hasItems(generated.backlog?.epics) ||
  hasItems(generated.backlog?.stories) ||
  hasItems(generated.backlog?.userStories) ||
  hasItems(generated.backlog?.features);

if (!hasBacklogShape) {
  throw new Error('Backlog parser found JSON but missing usable epics/stories structure. Top-level keys: ' + Object.keys(generated || {}).join(', '));
}

return [{ json: generated }];
